<script setup lang="ts">
import { computed, onMounted, onBeforeUnmount, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { packageRequest, packageDownload } from '@/lib/tender-package-api'
import PackageTree, { type TreeNode } from '@/components/tender-package/PackageTree.vue'
import RecognitionPanel from '@/components/tender-package/RecognitionPanel.vue'
import { useAuthStore } from '@/stores/auth'
const auth=useAuthStore(),importToken=ref('')
const route=useRoute(),router=useRouter()
const task=ref<any>(null),tasks=ref<any[]>([]),busy=ref(false),message=ref(''),reviewHtml=ref(''),frame=ref<HTMLIFrameElement|null>(null)
const password=ref(''),basis=ref(''),sourceKind=ref('mapping'),mappingOptions=ref('{}'),fieldPath=ref(''),fieldValue=ref(''),evidence=ref('[]')
const files=computed<any[]>(()=>task.value?.classified?.files||task.value?.manifest?.files||[])
const tree=computed(()=>{const roots:TreeNode[]=[];for(const file of files.value){let level=roots;let node:TreeNode|undefined;for(const name of file.logical_path.split('/')){node=level.find(x=>x.name===name);if(!node){node={name,children:[]};level.push(node)}level=node.children}if(node)node.file=file}return roots})
async function guard(fn:()=>Promise<unknown>){busy.value=true;message.value='';try{await fn()}catch(e){message.value=e instanceof Error?e.message:String(e);if(task.value?.id){try{await refresh()}catch{/* Preserve the original readable error. */}}}finally{busy.value=false}}
async function refresh(){if(!task.value?.id)return;task.value=await packageRequest(`/${task.value.id}`);if(task.value.ssot&&!reviewHtml.value){const r=await packageRequest(`/${task.value.id}/review-page`);reviewHtml.value=r.html}}
async function open(id:string){reviewHtml.value='';task.value={id};await refresh();await router.replace({path:'/tender-package',query:{id}})}
async function list(){tasks.value=await packageRequest('')}
async function importPrepared(){const r=await packageRequest(`/import-prepared/${importToken.value.trim()}`,'POST',{revision:1,arguments:{basis:basis.value}});await open(r.id);await list()}
async function action(op:string,args:any={}){await packageRequest(`/${task.value.id}/actions/${op}`,'POST',{revision:task.value.revision,arguments:args});await refresh();await list()}
async function upload(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;await guard(async()=>{const data=new FormData();data.append('file',file);const s=await packageRequest('/upload','POST',data);await open(s.id);await list()});(event.target as HTMLInputElement).value=''}
async function uploadSource(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;await guard(async()=>{const form=new FormData();form.append('file',file);form.append('revision',String(task.value.revision));const r=await packageRequest(`/${task.value.id}/sources`,'POST',form);await refresh();if(sourceKind.value==='mapping'){await action('mapping',{upload_id:r.upload_id,...JSON.parse(mappingOptions.value)})}else await action('source',{upload_id:r.upload_id,kind:sourceKind.value,basis:basis.value})});(event.target as HTMLInputElement).value=''}
async function bridge(event:MessageEvent){if(event.source!==frame.value?.contentWindow||event.data?.kind!=='package-review-request')return;const {id,path,body}=event.data;try{let result:any;if(path==='/state'){await refresh();result=task.value.review}else if(path==='/apply'){await action('review',body);result={saved:'任务版本 '+task.value.revision,message:'已记录当前登录用户、确认时间、依据及历史；须重新生成并验收产物'}}else throw Error('正式页面不支持此本地操作；真实资料选择自动用于下一次生成');frame.value?.contentWindow?.postMessage({kind:'package-review-reply',id,result:JSON.parse(JSON.stringify(result))},'*')}catch(e){frame.value?.contentWindow?.postMessage({kind:'package-review-reply',id,error:e instanceof Error?e.message:String(e)},'*')}}
async function field(){let value:any=fieldValue.value;try{value=JSON.parse(value)}catch{/* literal text */}await action('field',{path:fieldPath.value,value,basis:basis.value,evidence_refs:JSON.parse(evidence.value)})}
onMounted(()=>{window.addEventListener('message',bridge);void guard(async()=>{await list();if(typeof route.query.id==='string')await open(route.query.id)})})
onBeforeUnmount(()=>window.removeEventListener('message',bridge))
</script>
<template><main class="package-page"><h1>压缩包标书</h1><p>独立压缩包入口。普通文档继续使用原标书生成页面。当前仅输出待核验草稿，不自动认定可投标。</p><p class="notice">本轮跳过全量回归，仅做定向验证。人工核验完成后须另行同意全量回归及整包总验收。</p><p v-if="message" role="alert" class="error">{{message}}</p>
<section><h2>任务与上传</h2><input type="file" accept=".zip,.rar,.7z" :disabled="busy" @change="upload"><button :disabled="busy" @click="guard(list)">刷新任务</button><select :value="task?.id||''" :disabled="busy" @change="guard(()=>open(($event.target as HTMLSelectElement).value))"><option value="" disabled>选择任务</option><option v-for="s in tasks" :key="s.id" :value="s.id">{{s.name}} · {{s.status}}</option></select></section>
<section v-if="auth.isAdmin"><h2>导入既有交付成果</h2><p>只接受管理员在服务器准备并校验的交付包ID，不能输入本地文件路径。导入后仍保留所有未确认项。</p><input v-model="importToken" placeholder="服务器预备交付包ID"><input v-model="basis" placeholder="导入依据（必填）"><button :disabled="busy" @click="guard(importPrepared)">导入到当前登录账号</button></section>
<template v-if="task"><section><h2>阶段与目录树</h2><p>{{task.name}} · {{task.status}} · {{task.stage}} · 版本 {{task.revision}}</p><p v-if="task.error" class="error">{{task.error}}</p><input v-model="password" type="password" placeholder="加密包密码（不留存）"><button :disabled="busy||!task.archive||!!task.manifest" @click="guard(()=>action('unpack',{password}))">安全解包</button><button :disabled="busy||!task.manifest||!!task.ssot" @click="guard(()=>action('classify'))">识别角色与物料</button><PackageTree :nodes="tree" /></section>
<RecognitionPanel v-if="task.classified&&task.recognition" :classified="task.classified" :recognition="task.recognition" :files="files" :busy="busy" :frozen="!!task.ssot" @role="args=>guard(()=>action('role',args))" @material="args=>guard(()=>action('material',args))" @retire="args=>guard(()=>action('material_retire',args))" @export="guard(()=>action('material_export'))" />
<p v-else-if="task.classified">当前后端尚未提供识别结果展示契约，请在允许的部署窗口加载新后端代码。</p>
<section v-if="task.classified"><button :disabled="busy||!!task.ssot" @click="guard(()=>action('ssot'))">汇聚 SSOT</button><details v-if="task.mapping"><summary>供SSOT读取的最终映射（原模块二契约）</summary><pre>{{JSON.stringify(task.mapping,null,2)}}</pre></details></section>
<section v-if="task.classified"><h2>真实来源上传</h2><input v-model="basis" placeholder="本次来源批准/补录依据"><select v-model="sourceKind"><option value="mapping">固化ID—物料名称映射表</option><option v-if="task.ssot" value="product">供应商产品参数 DOCX</option><option v-if="task.ssot" value="quote_source">已批准的实际报价 XLSX</option></select><input v-if="sourceKind==='mapping'" v-model="mappingOptions" placeholder="可指定列号、sheet、encoding 的 JSON"><input type="file" :accept="sourceKind==='product'?'.docx':'.xlsx,.csv'" :disabled="busy" @change="uploadSource"><p>报价审批须填写上方依据；产品与ID的自动关联只作为来源引用，不代替响应/偏离人工结论。</p></section>
<section v-if="task.ssot"><h2>SSOT 与字段补录</h2><details><summary>字段、冲突与逐条来源</summary><pre>{{JSON.stringify(task.ssot,null,2)}}</pre></details><select v-model="fieldPath"><option value="">选择待确认字段</option><option v-for="p in [...new Set([...task.ssot.pending,...task.ssot.conflicts])]" :key="String(p)">{{p}}</option></select><input v-model="fieldValue" placeholder="实际值或 JSON"><textarea v-model="evidence" placeholder="SSOT 原文证据数组：document_id、locator、quote"></textarea><button :disabled="busy" @click="guard(field)">保存字段核验</button></section>
<section v-if="task.ssot"><h2>正式人工核验与生成</h2><p>冲突、响应、标包报价和商务核验均在本页完成。当前登录账号为最终记录的确认人。保存后重新生成才能更新文件。</p><button :disabled="busy" @click="guard(()=>action('library'))">读取资料库真实候选</button><button :disabled="busy" @click="guard(()=>action('generate'))">按已确认数据生成草稿</button><iframe v-if="reviewHtml" ref="frame" :srcdoc="reviewHtml" sandbox="allow-scripts allow-downloads" title="正式压缩包标书人工核验" /></section>
<section v-if="task.result"><h2>按标包 / 固化ID查看产物</h2><p>结构检查产物 · 视觉状态：{{task.result.visual_validation?.visual_status}}。rendered_pending_review 仅表示已渲染，未表示验收通过。</p><p v-for="p in task.result.packages" :key="p.key">标包：{{p.package_code||'待分配'}} / {{p.key}} · 固化ID：{{p.material_ids.join('、')}}</p><ul><li v-for="(a,i) in task.result.artifacts" :key="a.path"><button :disabled="busy" @click="guard(()=>packageDownload(task.id,Number(i),a.path.split(/[\\/]/).pop()))">下载 {{a.path}}</button></li></ul><details open><summary>warnings / 人工核对清单</summary><pre>{{JSON.stringify(task.result.warnings,null,2)}}</pre></details></section>
<details><summary>处理与人工确认历史</summary><pre>{{JSON.stringify(task.history,null,2)}}</pre></details></template></main></template>
<style scoped>.package-page{padding:24px;max-width:1600px;margin:auto;color:var(--foreground,#172033)}section{border:1px solid #d5dbe4;border-radius:10px;padding:20px;margin:20px 0;background:var(--card,#fff)}h1{font-size:26px}h2{font-size:20px;margin-bottom:15px}input,select,button,textarea{border:1px solid #b5c0ce;padding:8px;margin:5px;border-radius:5px}button{background:#164b83;color:white;cursor:pointer}button:disabled{opacity:.45}pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:60vh;overflow:auto}small{display:block;overflow-wrap:anywhere;color:#64748b}.error{color:#b91c1c}.notice{background:#fff4cf;padding:12px}.scroll{max-height:50vh;overflow:auto}table{border-collapse:collapse;width:100%}td,th{border:1px solid #d5dbe4;padding:8px;text-align:left}iframe{border:0;width:100%;height:1000px;margin-top:20px}textarea{display:block;width:95%;min-height:70px}</style>


